def modp(n, p):
    if n == 0:
        return 1
    if p == 1:
        return 0

    def power(base, exp, mod):
        result = 1
        base = base % mod
        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % mod
            exp = exp // 2
            base = (base * base) % mod
        return result

    return power(2, n, p)

print(modp(3, 5))    # Output: 3
print(modp(1101, 101))    # Output: 2
print(modp(0, 101))    # Output: 1
print(modp(3, 11))    # Output: 8
print(modp(100, 101))    # Output: 1

